def top_k(lst, k):
    tmp = []
    while len(lst) > 0:
        tmp.append(max(lst))
        lst.remove(max(lst))
    return tmp[:k]

def top_k(lst, k):
    sort = []
    while len(sort) < k:
        biggest = lst[0]
        for element in lst:
            if element > biggest:
                biggest = element
        lst.remove(biggest)
        sort.append(biggest)
    return sort

